import type { Meta, StoryObj } from '@storybook/angular';
import { TuiButton } from '@vsk/ui-kit/taiga-ui/core';
import { TuiButtonLoading } from '@vsk/ui-kit/taiga-ui/kit';

import { buildButtonParameters } from './button.story-config';

const TAIGA_APPEARANCES = [
  'primary',
  'primary-destructive',
  'primary-grayscale',
  'secondary',
  'secondary-destructive',
  'secondary-grayscale',
  'accent',
  'action',
  'action-destructive',
  'action-grayscale',
  'outline',
  'outline-destructive',
  'outline-grayscale',
  'flat',
  'flat-destructive',
  'flat-grayscale',
  'floating',
  'glass',
  'neutral',
  'positive',
  'negative',
  'warning',
  'info',
  'icon',
  'textfield',
] as const;

type TaigaAppearance = (typeof TAIGA_APPEARANCES)[number];
type TaigaSize = 'xs' | 's' | 'm' | 'l' | 'xl';
type TaigaInteractiveState = 'hover' | 'active' | 'disabled';
type TaigaAriaLive = 'off' | 'polite' | 'assertive';

interface ButtonApiStoryArgs {
  label: string;
  appearance: TaigaAppearance;
  appearanceMode: string | null;
  appearanceState: TaigaInteractiveState | null;
  appearanceFocus: boolean | null;
  size: TaigaSize;
  iconStart: string | null;
  iconEnd: string | null;
  loading: boolean;
  loadingLabel: string | null;
  disabled: boolean;
  block: boolean;
  vertical: boolean;
  type: 'button' | 'submit' | 'reset';
  ariaLabel: string | null;
  ariaDescribedBy: string | null;
  ariaControls: string | null;
  ariaExpanded: boolean | null;
  ariaPressed: boolean | null;
  ariaLive: TaigaAriaLive | null;
  dataTestId: string | null;
}

const DOCS_REFERENCE = [
  'Taiga UI · Appearance: "Используйте `tuiAppearanceMode`, чтобы эмулировать CSS-состояния `:checked`/`:invalid` для outline-вариантов (пример: `<button appearance="outline" tuiAppearanceMode="checked" tuiButton ...>`)"',
  'Taiga UI · Icons: "В разделе Icons приведён пример `<button appearance="outline" iconEnd="@tui.chevron-down" size="s" tuiButton ...>More</button>`, который демонстрирует входы `iconStart`/`iconEnd`."',
  'Taiga UI · Loading: "Шаблон `<button iconStart="@tui.clock" tuiButton type="button" [loading]="loading$ | async">Click to start</button>` подчёркивает использование `[loading]` и компонента `TuiButtonLoading`."',
  'Taiga UI · Vertical: "Пример `<button tuiButton tuiButtonVertical ...>` включает вертикальный режим за счёт атрибута `tuiButtonVertical`."',
  'Источник: https://taiga-ui.dev/components/button',
].join('\n\n');

const BUTTON_API_TEMPLATE = `
  <button
    tuiButton
    class="vsk-button-api"
    [appearance]="appearance"
    [size]="size"
    [disabled]="disabled"
    [loading]="loading ? (loadingLabel?.trim() || true) : null"
    [iconStart]="iconStart || null"
    [iconEnd]="iconEnd || null"
    [tuiAppearanceMode]="appearanceMode?.trim() ? appearanceMode : null"
    [tuiAppearanceState]="appearanceState || null"
    [tuiAppearanceFocus]="appearanceFocus"
    [attr.type]="type"
    [attr.data-testid]="dataTestId || null"
    [attr.aria-label]="ariaLabel || label"
    [attr.aria-describedby]="ariaDescribedBy || null"
    [attr.aria-controls]="ariaControls || null"
    [attr.aria-expanded]="ariaExpanded === null ? null : ariaExpanded"
    [attr.aria-pressed]="ariaPressed === null ? null : ariaPressed"
    [attr.aria-live]="ariaLive || null"
    [attr.aria-busy]="loading ? 'true' : null"
    [attr.tuiButtonVertical]="vertical ? '' : null"
    [style.display]="block ? 'flex' : null"
    [style.width.%]="block ? 100 : null"
    [style.justifyContent]="block ? 'center' : null"
  >
    <span class="vsk-button-api__label">{{ label }}</span>
  </button>
`;

const meta: Meta<ButtonApiStoryArgs> = {
  id: 'atoms-button-full-api',
  title: 'Atoms/Кнопка — tuiButton/Полный API',
  tags: ['autodocs', 'beta'],
  parameters: buildButtonParameters({
    docsDescription:
      'Полный playground для `tuiButton`: доступны appearance, размеры, иконки, вертикальный режим, атрибуты доступности и встроенный `[loading]`. ' +
      'Ниже приведена выдержка из официальной документации Taiga UI:\n\n' +
      DOCS_REFERENCE,
    includeDesign: true,
    controlsDisabled: false,
  }),
  argTypes: {
    label: {
      control: 'text',
      description: 'Текст кнопки.',
    },
    appearance: {
      control: 'select',
      options: TAIGA_APPEARANCES,
      description: 'Темы Taiga UI из `TuiAppearance`.',
    },
    appearanceMode: {
      control: 'text',
      description: 'Строка для `tuiAppearanceMode` (например, "checked invalid").',
    },
    appearanceState: {
      control: {
        type: 'select',
        labels: { null: 'auto' },
      },
      options: [null, 'hover', 'active', 'disabled'],
      description: 'Принудительное состояние `tuiAppearanceState`.',
    },
    appearanceFocus: {
      control: {
        type: 'select',
        labels: { null: 'auto', true: 'в фокусе', false: 'без фокуса' },
      },
      options: [null, true, false],
      description: 'Управление `tuiAppearanceFocus`.',
    },
    size: {
      control: 'inline-radio',
      options: ['xs', 's', 'm', 'l', 'xl'],
      description: 'Высота кнопки (`size` вход `tuiButton`).',
    },
    iconStart: {
      control: 'text',
      description: 'Левая иконка (`iconStart`).',
    },
    iconEnd: {
      control: 'text',
      description: 'Правая иконка (`iconEnd`).',
    },
    loading: {
      control: 'boolean',
      description: 'Активирует встроенный `TuiButtonLoading`.',
    },
    loadingLabel: {
      control: 'text',
      description: 'Текст индикатора загрузки (передаётся как строка в `[loading]`).',
    },
    disabled: {
      control: 'boolean',
    },
    block: {
      control: 'boolean',
      description: 'Растянуть кнопку на 100% ширины.',
    },
    vertical: {
      control: 'boolean',
      description: 'Добавляет атрибут `tuiButtonVertical`.',
    },
    type: {
      control: 'inline-radio',
      options: ['button', 'submit', 'reset'],
    },
    ariaLabel: {
      control: 'text',
    },
    ariaDescribedBy: {
      control: 'text',
    },
    ariaControls: {
      control: 'text',
    },
    ariaExpanded: {
      control: {
        type: 'select',
        labels: { null: 'auto' },
      },
      options: [null, true, false],
    },
    ariaPressed: {
      control: {
        type: 'select',
        labels: { null: 'auto' },
      },
      options: [null, true, false],
    },
    ariaLive: {
      control: {
        type: 'select',
        labels: { null: 'off (auto)' },
      },
      options: [null, 'off', 'polite', 'assertive'],
    },
    dataTestId: {
      control: 'text',
    },
  },
  args: {
    label: 'Игровая кнопка Taiga',
    appearance: 'primary',
    appearanceMode: '',
    appearanceState: null,
    appearanceFocus: null,
    size: 'm',
    iconStart: '@tui.search',
    iconEnd: '@tui.chevron-down',
    loading: false,
    loadingLabel: 'Загрузка...',
    disabled: false,
    block: false,
    vertical: false,
    type: 'button',
    ariaLabel: 'Игровая кнопка Taiga',
    ariaDescribedBy: null,
    ariaControls: null,
    ariaExpanded: null,
    ariaPressed: null,
    ariaLive: null,
    dataTestId: 'button-api-playground',
  },
};

export default meta;

type Story = StoryObj<ButtonApiStoryArgs>;

export const FullAPI: Story = {
  name: 'Playground/Полный набор атрибутов',
  render: (args) => ({
    props: args,
    moduleMetadata: {
      imports: [TuiButton, TuiButtonLoading],
    },
    template: BUTTON_API_TEMPLATE,
  }),
  parameters: {
    docs: {
      description: {
        story:
          'История повторяет все входы `tuiButton`, включая `appearance`, `size`, `iconStart`/`iconEnd`, `[loading]`, `tuiButtonVertical` и ARIA-атрибуты.' +
          ' Используйте контролы, чтобы собрать нужную комбинацию перед копированием кода.',
      },
    },
  },
};

import type { Meta, StoryObj } from '@storybook/angular';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule, FormControl } from '@angular/forms';
import { TuiLabel } from '@vsk/ui-kit/taiga-ui/core';
import { TuiPlatform } from '@vsk/ui-kit/taiga-ui/cdk';
import { TuiSwitch } from '@vsk/ui-kit/taiga-ui/kit';
import {
  createInvalidControl,
  createShowcaseVariants,
  createShowcaseControlResolver,
  DEFAULT_SHOWCASE_SIZES,
  VskShowcaseComponent,
  VskShowcaseOption,
  VskShowcaseSize,
  VskShowcasePlatform,
  VskShowcaseVariant,
} from '../../storybook/showcase/vsk-showcase.component';

type TuiSizeS = 's' | 'm';
type TuiPlatformName = VskShowcasePlatform;
type SwitchShowcaseSize = Exclude<VskShowcaseSize, 'l'>;

// Модель значения для витрины: либо простое ngModel, либо formControl с ошибкой/валидацией.
interface SwitchShowcaseNgModel {
  kind: 'ngModel';
  value: boolean;
}

interface SwitchShowcaseFormControl {
  kind: 'formControl';
  createControl: () => FormControl<boolean>;
}

type SwitchShowcaseModel = SwitchShowcaseNgModel | SwitchShowcaseFormControl;

// Данные, которые попадут в шаблон элемента витрины.
interface SwitchShowcaseVariantData {
  disabled: boolean;
  showIcons: boolean;
  model: SwitchShowcaseModel;
}
type SwitchShowcaseVariant = VskShowcaseVariant<SwitchShowcaseVariantData>;

// Переключатель поддерживает только S/M, поэтому исключаем L.
const switchSizes: VskShowcaseOption<SwitchShowcaseSize>[] = DEFAULT_SHOWCASE_SIZES.filter(
  (size): size is VskShowcaseOption<SwitchShowcaseSize> => size.value !== 'l',
);

// Генерируем все комбинации значений: disabled x showIcons x model.
const defaultVariants: SwitchShowcaseVariant[] = createShowcaseVariants<SwitchShowcaseVariantData>({
  prefix: 'Переключатель в состояниях',
  dimensions: [
    {
      key: 'disabled',
      label: 'disabled',
      values: [
        { label: 'выключено', value: false, id: 'off' },
        { label: 'включено', value: true, id: 'on' },
      ],
    },
    {
      key: 'showIcons',
      label: 'showIcons',
      values: [
        { label: 'нет', value: false, id: 'no' },
        { label: 'есть', value: true, id: 'yes' },
      ],
    },
    {
      key: 'model',
      label: 'ngModel',
      values: [
        // Обычные состояния через ngModel.
        { label: 'включено', value: { kind: 'ngModel', value: true }, id: 'ng-on' },
        { label: 'выключено', value: { kind: 'ngModel', value: false }, id: 'ng-off' },
        // Состояния с ошибкой через FormControl.
        {
          label: 'ошибка (on)',
          title: 'formControl=ошибка (on)',
          value: { kind: 'formControl', createControl: () => createInvalidControl(true) },
          id: 'fc-on',
        },
        {
          label: 'ошибка (off)',
          title: 'formControl=ошибка (off)',
          value: { kind: 'formControl', createControl: () => createInvalidControl(false) },
          id: 'fc-off',
        },
      ],
    },
  ],
  mapData: (values) => ({
    // Читаем из словаря комбинации по ключу измерения.
    disabled: values['disabled'] as boolean,
    showIcons: values['showIcons'] as boolean,
    model: values['model'] as SwitchShowcaseModel,
  }),
});

interface SwitchStoryArgs {
  checked: boolean;
  disabled: boolean;
  showIcons: boolean;
  size: TuiSizeS;
  platform: TuiPlatformName;
  label: string | null;
  helperText: string | null;
  ariaLabel: string | null;
}

const meta: Meta<SwitchStoryArgs> = {
  id: 'atoms-switch',
  title: 'Atoms/Переключатель — tuiSwitch',
  tags: ['autodocs', 'beta'],
  parameters: {
    layout: 'padded',
    design: {
      type: 'image',
      name: 'Дизайн',
      url: 'assets/atoms/switch/figma/image.png',
      scale: 0.35,
      offset: [-200, 120],
    },
    docs: {
      description: {
        component:
          'Переключатель на базе директивы `tuiSwitch` (Taiga UI, пакет KIT), применяется на нативном `<input type="checkbox">`. Компонент поддерживает двоичное состояние on/off, опциональные иконки внутри бегунка и платформенные различия отображения (web, Android, iOS) через директиву `tuiPlatform`.\n\n' +
          'Основные входные параметры: `[(ngModel)]` или `[formControl]` для управления значением, `[disabled]` для недоступного состояния, `[showIcons]` для отображения иконок, `[size]` со значениями `"s" | "m"`. Для демонстрации платформ используйте `[tuiPlatform]="platform"`.\n\n' +
          'Доступность: элемент имеет семантику переключателя на базе нативного чекбокса. В примерах Taiga UI подпись оформляется через `<label tuiLabel>`, оборачивающий и сам переключатель, и текст. Если визуальной метки нет, используйте `aria-label`. Для вспомогательного текста используйте `aria-describedby`, связывая элемент с описанием (например, скрытым текстом). Для состояний валидации через реактивные формы корректно отображаются `aria-invalid` и стили ошибки.',
      },
    },
  },
  argTypes: {
    size: {
      options: ['s', 'm'],
      control: { type: 'inline-radio' },
      description: 'Размер переключателя (S/M).',
    },
    platform: {
      options: ['web', 'android', 'ios'],
      control: { type: 'inline-radio' },
      description: 'Платформа визуализации через директиву `tuiPlatform`.',
    },
    checked: { control: 'boolean', description: 'Текущее состояние: включён/выключен.' },
    disabled: { control: 'boolean', description: 'Недоступное состояние.' },
    showIcons: { control: 'boolean', description: 'Показывать иконки в бегунке.' },
    label: { control: 'text', description: 'Текстовая метка для переключателя.' },
    helperText: {
      control: 'text',
      description:
        'Вспомогательный текст. Если задан, подключается к элементу через aria-describedby.',
    },
    ariaLabel: {
      control: 'text',
      description:
        'Альтернативная метка через `aria-label`, используется, когда видимого label нет.',
    },
  },
  args: {
    checked: false,
    disabled: false,
    showIcons: true,
    size: 'm',
    platform: 'web',
    label: 'Использовать биометрию',
    helperText: 'Переключает вход по отпечатку/Face ID при поддержке устройством',
    ariaLabel: null,
  },
};

export default meta;

type Story = StoryObj<SwitchStoryArgs>;

export const Playground: Story = {
  parameters: {
    docs: {
      description: {
        story:
          'Песочница с управляемыми параметрами. Метка оформлена через обёртку `<label tuiLabel>`, как в примерах Taiga UI; при отсутствии видимой метки используйте `aria-label`. Вспомогательный текст подключён к переключателю через `aria-describedby`.',
      },
    },
  },
  render: (args) => ({
    props: args,
    moduleMetadata: {
      imports: [CommonModule, FormsModule, TuiLabel, TuiPlatform, TuiSwitch],
    },
    template: `
      <section [tuiPlatform]="platform" aria-label="Playground">
        <label tuiLabel>
          <input
            tuiSwitch
            type="checkbox"
            [(ngModel)]="checked"
            [disabled]="disabled"
            [showIcons]="showIcons"
            [size]="size"
            [attr.aria-label]="!label ? ariaLabel : null"
            [attr.aria-describedby]="helperText ? 'switch-helper' : null"
          />
          @if (label) {
            <span>{{ label }}</span>
          }
        </label>
        @if (helperText) {
          <p id="switch-helper" class="vsk-visually-hidden">
            {{ helperText }}
          </p>
        }
      </section>
    `,
  }),
};

export const Showcase: Story = {
  parameters: {
    controls: { disabled: true },
    viewport: null,
    docs: {
      description: {
        story:
          'Подборка ключевых состояний по официальной документации Taiga UI: размеры S/M, доступность, недоступные состояния, и ошибка валидации через реактивные формы. Также показаны платформенные различия (web/android/ios) через `tuiPlatform` и ряд примеров из дизайн-макетов с логическими размерами S/M/L (в Taiga UI для переключателя доступны размеры `s` и `m`, размер L реализуется на уровне дизайн-системы поверх `m`).',
      },
    },
  },
  render: () => {
    // Кешируем FormControl по ключу, чтобы каждый вариант был стабильным.
    const resolveControl = createShowcaseControlResolver();

    return {
      props: {
        // Передаем только разрешенные размеры и список вариантов.
        sizes: switchSizes,
        variants: defaultVariants,
        // Просим витрину оборачивать элементы в <label tuiLabel>.
        resolveControl,
        wrapInLabel: true,
      },
      moduleMetadata: {
        imports: [VskShowcaseComponent, FormsModule, ReactiveFormsModule, TuiSwitch],
      },
      template: `
        <!-- Шаблон одного элемента витрины для переключателя. -->
        <ng-template #item let-variant let-size="size" let-key="key">
          @switch (variant.data.model.kind) {
            @case ('ngModel') {
              <!-- size.value берется из входного списка sizes -->
              <input
                tuiSwitch
                type="checkbox"
                [ngModel]="variant.data.model.value"
                [disabled]="variant.data.disabled"
                [showIcons]="variant.data.showIcons"
                [size]="size.value"
                [attr.aria-label]="variant.title"
              />
            }
            @case ('formControl') {
              <!-- FormControl создается на каждый уникальный ключ витрины -->
              <input
                tuiSwitch
                type="checkbox"
                [formControl]="resolveControl(key, variant.data.model.createControl)"
                [disabled]="variant.data.disabled"
                [showIcons]="variant.data.showIcons"
                [size]="size.value"
                [attr.aria-label]="variant.title"
              />
            }
          }
        </ng-template>

        <!-- Общая витрина, которая сама разбивает на темы/платформы/размеры. -->
        <vsk-showcase
          [sizes]="sizes"
          [variants]="variants"
          [wrapInLabel]="wrapInLabel"
          [itemTemplate]="item"
        />
      `,
    };
  },
};

import type { Meta, StoryObj } from '@storybook/angular';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule, FormControl } from '@angular/forms';
import { TuiLabel } from '@vsk/ui-kit/taiga-ui/core';
import { TuiPlatform } from '@vsk/ui-kit/taiga-ui/cdk';
import { TuiSwitch } from '@vsk/ui-kit/taiga-ui/kit';
import {
  createInvalidControl,
  createShowcaseVariants,
  createShowcaseControlResolver,
  DEFAULT_SHOWCASE_SIZES,
  VskShowcaseComponent,
  VskShowcaseOption,
  VskShowcaseSize,
  VskShowcasePlatform,
  VskShowcaseVariant,
} from '../../storybook/showcase/vsk-showcase.component';

type TuiSizeS = 's' | 'm';
type TuiPlatformName = VskShowcasePlatform;
type SwitchShowcaseSize = Exclude<VskShowcaseSize, 'l'>;

// Модель значения для витрины: либо простое ngModel, либо formControl с ошибкой/валидацией.
interface SwitchShowcaseNgModel {
  kind: 'ngModel';
  value: boolean;
}

interface SwitchShowcaseFormControl {
  kind: 'formControl';
  createControl: () => FormControl<boolean>;
}

type SwitchShowcaseModel = SwitchShowcaseNgModel | SwitchShowcaseFormControl;

// Данные, которые попадут в шаблон элемента витрины.
interface SwitchShowcaseVariantData {
  disabled: boolean;
  showIcons: boolean;
  model: SwitchShowcaseModel;
}
type SwitchShowcaseVariant = VskShowcaseVariant<SwitchShowcaseVariantData>;

// Переключатель поддерживает только S/M, поэтому исключаем L.
const switchSizes: VskShowcaseOption<SwitchShowcaseSize>[] = DEFAULT_SHOWCASE_SIZES.filter(
  (size): size is VskShowcaseOption<SwitchShowcaseSize> => size.value !== 'l',
);

// Генерируем все комбинации значений: disabled x showIcons x model.
const defaultVariants: SwitchShowcaseVariant[] = createShowcaseVariants<SwitchShowcaseVariantData>({
  prefix: 'Переключатель в состояниях',
  dimensions: [
    {
      key: 'disabled',
      label: 'disabled',
      values: [
        { label: 'выключено', value: false, id: 'off' },
        { label: 'включено', value: true, id: 'on' },
      ],
    },
    {
      key: 'showIcons',
      label: 'showIcons',
      values: [
        { label: 'нет', value: false, id: 'no' },
        { label: 'есть', value: true, id: 'yes' },
      ],
    },
    {
      key: 'model',
      label: 'ngModel',
      values: [
        // Обычные состояния через ngModel.
        { label: 'включено', value: { kind: 'ngModel', value: true }, id: 'ng-on' },
        { label: 'выключено', value: { kind: 'ngModel', value: false }, id: 'ng-off' },
        // Состояния с ошибкой через FormControl.
        {
          label: 'ошибка (on)',
          title: 'formControl=ошибка (on)',
          value: { kind: 'formControl', createControl: () => createInvalidControl(true) },
          id: 'fc-on',
        },
        {
          label: 'ошибка (off)',
          title: 'formControl=ошибка (off)',
          value: { kind: 'formControl', createControl: () => createInvalidControl(false) },
          id: 'fc-off',
        },
      ],
    },
  ],
  mapData: (values) => ({
    // Читаем из словаря комбинации по ключу измерения.
    disabled: values['disabled'] as boolean,
    showIcons: values['showIcons'] as boolean,
    model: values['model'] as SwitchShowcaseModel,
  }),
});

interface SwitchStoryArgs {
  checked: boolean;
  disabled: boolean;
  showIcons: boolean;
